function joinRaw(strings, ...values) {
  return strings.raw.join("|") + " " + values.length;
}

const seen = [];

function keep(strings) {
  seen.push(strings);
}

console.log(joinRaw`x\ny${1}`);
console.log(joinRaw`${"a"}${"b"}`);
for (let i = 0; i < 2; i++) keep`same`;
console.log(seen[0] === seen[1]);
